(function(){var A=window.ANNONCES||{},n=new Date(),b=A.banniere;function enCours(o){return!!(o&&o.active&&!(o.debut&&new Date(o.debut+'T00:00:00')>n)&&!(o.fin&&new Date(o.fin+'T23:59:59')<n))}if(A.bannieres){b=null;for(var i=0;i<A.bannieres.length;i++){if(enCours(A.bannieres[i])){b=A.bannieres[i];break}}}if(!enCours(b))return;try{if(localStorage.getItem('lumiaBanniere|'+(b.titre||b.texte||'')+'|'+(b.debut||'')+'|'+(b.fin||'')))return}catch(e){}document.documentElement.classList.add('has-banniere')})();